WITH item_sales AS ( SELECT i.i_item_sk, i.i_brand, i.i_product_name, i.i_current_price, AVG(ws.ws_sales_price) AS avg_sales_price, SUM(ws.ws_quantity) AS total_qty FROM item i JOIN web_sales ws ON ws.ws_item_sk = i.i_item_sk GROUP BY i.i_item_sk, i.i_brand, i.i_product_name, i.i_current_price ), warehouse_for_item_counts AS ( SELECT ws.ws_item_sk, ws.ws_warehouse_sk, COUNT(*) AS cnt FROM web_sales ws GROUP BY ws.ws_item_sk, ws.ws_warehouse_sk ), warehouse_for_item AS ( SELECT ws_item_sk, ws_warehouse_sk, ROW_NUMBER() OVER (PARTITION BY ws_item_sk ORDER BY cnt DESC) AS wh_rank FROM warehouse_for_item_counts ), item_rank AS ( SELECT isales.*, CASE WHEN isales.i_current_price > isales.avg_sales_price * 1.20 THEN 'Overpriced' WHEN isales.i_current_price < isales.avg_sales_price * 0.80 THEN 'Underpriced' ELSE 'Fairly Priced' END AS price_category, RANK() OVER (PARTITION BY isales.i_brand ORDER BY (isales.i_current_price - isales.avg_sales_price) DESC) AS price_diff_rank FROM item_sales isales ) SELECT ir.i_brand, ir.i_product_name, ir.i_current_price, ir.avg_sales_price, ir.price_category, ir.price_diff_rank, w.w_warehouse_name AS top_warehouse FROM item_rank ir LEFT JOIN warehouse_for_item wfi ON ir.i_item_sk = wfi.ws_item_sk AND wfi.wh_rank = 1 LEFT JOIN warehouse w ON wfi.ws_warehouse_sk = w.w_warehouse_sk WHERE ir.price_diff_rank <= 10 ORDER BY ir.i_brand, ir.price_diff_rank
